create or replace view public.payment_history with(security_invoker=true) as
 select p.id,p.owner_id,'commitment'::text as kind,p.commitment_id as entity_id,p.entry_id,p.due_date,p.undone_entry,e.created_at,p.released::text,'0'::text as principal,'0'::text as interest,e.description,e.effective_date,e.currency,(select sum(-amount)::text from public.lines where entry_id=e.id and bucket='asset') as amount from public.commitment_payments p join public.entries e on e.id=p.entry_id
 union all select p.id,p.owner_id,'debt',p.debt_id,p.entry_id,p.due_date,p.undone_entry,e.created_at,p.released::text,p.principal::text,p.interest::text,e.description,e.effective_date,e.currency,(select sum(-amount)::text from public.lines where entry_id=e.id and bucket='asset') as amount from public.debt_payments p join public.entries e on e.id=p.entry_id;
create view public.allocation_history with(security_invoker=true) as select b.id,b.owner_id,b.entry_id,b.undone,b.created_at,e.description,e.currency,coalesce(sum(g.amount),0)::text as amount from public.allocation_batches b join public.entries e on e.id=b.entry_id left join public.goal_events g on g.batch_id=b.id group by b.id,e.id;
grant select on public.allocation_history to authenticated;
